import json
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent


def load_params(path):
    p = os.environ.get('PARAMS_PATH', str(path))
    try:
        with open(p, 'r', encoding='utf-8') as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"parameters.json not found at {p}; using defaults", file=sys.stderr)
    except json.JSONDecodeError as e:
        print(f"Invalid parameters.json ({e}); using defaults", file=sys.stderr)
    # Safe defaults
    return {
        'population_size': 1000,
        'simulation_days': 60,
        'time_steps': 60
    }


def load_param_definitions(path, params):
    p = os.environ.get('PARAM_DEFS_PATH', str(path))
    try:
        with open(p, 'r', encoding='utf-8') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"parameter_definitions.json issue ({e}); using minimal defaults", file=sys.stderr)
        return {
            'adoption': {
                'p': 0.03,
                'q': 0.38
            }
        }


def normalize_params(params):
    out = dict(params or {})
    # Coerce
    for k in ('population_size', 'simulation_days', 'time_steps'):
        if k in out:
            try:
                out[k] = int(out[k])
            except (TypeError, ValueError):
                out[k] = 0
    if out.get('time_steps', 0) <= 0:
        out['time_steps'] = max(1, out.get('simulation_days', 60))
    # Caps to avoid timeouts
    out['population_size'] = max(1, min(out.get('population_size', 1000), 100000))
    out['time_steps'] = max(1, min(out.get('time_steps', 60), 10000))
    return out


# Ensure Simulation is available
try:
    from simulation import Simulation  # If present in project
except Exception:
    class Simulation:
        def __init__(self, params, param_defs):
            self.params = params
            self.param_defs = param_defs
            self._adoption = 0.0
            self._history = []
        def run(self, start_step=0, steps=60):
            steps = int(steps)
            p = float(self.param_defs.get('adoption', {}).get('p', 0.03))
            q = float(self.param_defs.get('adoption', {}).get('q', 0.38))
            N = max(1, int(self.params.get('population_size', 1000)))
            A = 0  # adopters
            for t in range(start_step, start_step + steps):
                F = A / N
                # Simple Bass-like increment (deterministic approximation)
                dA = (p + q * F) * (N - A) / max(1, steps)
                A = min(N, A + int(round(dA)))
                self._history.append(A / N)
                if self._history[-1] >= 0.999:  # early stop
                    break
            self._adoption = self._history[-1] if self._history else 0.0
        def evaluate(self):
            art = list(self._history)
            t70 = None
            for i, v in enumerate(art):
                if v >= 0.70:
                    t70 = i
                    break
            return {
                'final_adoption_rate': self._adoption,
                'time_to_threshold_70': t70,
                'adoption_rate_over_time': art
            }


def main():
    # Optional deterministic quick test
    if os.environ.get('QUICK_TEST', '0') == '1':
        try:
            import random
            random.seed(0)
        except Exception:
            pass
    params = load_params(PROJECT_ROOT / 'parameters.json')
    if os.environ.get('QUICK_TEST', '0') == '1':
        params['population_size'] = 50
        params['simulation_days'] = 10
    params = normalize_params(params)
    defs_ = load_param_definitions(PROJECT_ROOT / 'parameter_definitions.json', params)
    sim = Simulation(params, defs_)
    steps = int(params.get('time_steps', 60))
    try:
        sim.run(0, steps)
    except TypeError:
        # Fallback if Simulation.run expects only total steps
        sim.run(steps)
    metrics = sim.evaluate() or {}
    return {
        'final_adoption_rate': float(metrics.get('final_adoption_rate', 0.0)),
        'time_to_threshold_70': metrics.get('time_to_threshold_70'),
        'adoption_rate_over_time': list(metrics.get('adoption_rate_over_time', []))
    }

# Execute main for both direct execution and sandbox wrapper invocation
main()

